result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "asm.py", "content": """"Two-pass assembler for the stack VM defined in machine.py."""

OPCODES = {
    "PUSH": 1,
    "LOAD": 2,
    "STORE": 3,
    "ADD": 4,
    "SUB": 5,
    "MUL": 6,
    "CMP": 7,
    "JMP": 8,
    "JLT": 9,
    "JEQ": 10,
    "OUT": 11,
    "HALT": 12,
}
MNEMONICS = {v: k for k, v in OPCODES.items()}

# Mnemonics that take an integer operand (register number or immediate/jump target).
_HAS_ARG = {"PUSH", "LOAD", "STORE", "JMP", "JLT", "JEQ"}
_REG_OPS = {"LOAD", "STORE"}
_NUM_REGS = 8


class AsmError(Exception):
    """Assembly error with source line number."""

    def __init__(self, message, lineno=None):
        self.lineno = lineno
        prefix = f"line {lineno}: " if lineno is not None else ""
        super().__init__(prefix + message)


def _parse_int(token):
    try:
        return int(token, 0)  # allows decimal and 0x... forms
    except ValueError:
        raise ValueError(f"invalid integer {token!r}")


def assemble(src):
    """Assemble source text into a flat list of ints: [op, arg, op, arg, ...].

    Every instruction occupies exactly two words so addresses are trivially
    computable: instruction i lives at address 2*i.
    Pass 1 computes label addresses; pass 2 emits code resolving labels.
    """
    # ---- pass 1: tokenize and record label addresses -------------------
    lines = []  # (lineno, mnemonic, operand_token_or_None)
    labels = {}
    addr = 0
    for lineno, raw in enumerate(src.splitlines(), start=1):
        line = raw.split(";", 1)[0].strip()
        while True:
            # a label may be followed by an instruction on the same line
            head, sep, rest = line.partition(":")
            if sep:
                name = head.strip()
                if not name or any(c.isspace() for c in name):
                    raise AsmError(f"bad label {head.strip()!r}", lineno)
                if name in labels:
                    raise AsmError(f"duplicate label {name!r}", lineno)
                labels[name] = addr
                line = rest.strip()
            else:
                break
        if not line:
            continue
        parts = line.split()
        mnemonic = parts[0].upper()
        if mnemonic not in OPCODES:
            raise AsmError(f"unknown mnemonic {parts[0]!r}", lineno)
        arg_tok = None
        if mnemonic in _HAS_ARG:
            if len(parts) != 2:
                raise AsmError(f"{mnemonic} expects exactly one operand", lineno)
            arg_tok = parts[1]
        elif len(parts) != 1:
            raise AsmError(f"{mnemonic} takes no operands", lineno)
        lines.append((lineno, mnemonic, arg_tok))
        addr += 2

    # ---- pass 2: emit code ---------------------------------------------
    out = []
    for lineno, mnemonic, arg_tok in lines:
        op = OPCODES[mnemonic]
        if mnemonic == "PUSH":
            try:
                arg = _parse_int(arg_tok)
            except ValueError as e:
                raise AsmError(str(e), lineno)
            out.extend([op, arg])
        elif mnemonic in _REG_OPS:
            try:
                reg = _parse_int(arg_tok)
            except ValueError as e:
                raise AsmError(str(e), lineno)
            if not 0 <= reg < _NUM_REGS:
                raise AsmError(
                    f"register must be 0..{_NUM_REGS - 1}, got {reg}", lineno
                )
            out.extend([op, reg])
        elif mnemonic in ("JMP", "JLT", "JEQ"):
            target = arg_tok
            if target not in labels:
                raise AsmError(f"undefined label {target!r}", lineno)
            out.extend([op, labels[target]])
        else:  # ADD, SUB, MUL, CMP, OUT, HALT
            out.extend([op, 0])
    return out


def disasm(bytecode):
    """Disassemble flat bytecode back into assembly source text."""
    if len(bytecode) % 2 != 0:
        raise AsmError("bytecode length must be even")

    def fmt_arg(op, arg):
        m = MNEMONICS[op]
        if m == "PUSH":
            return str(arg)
        if m in _REG_OPS:
            return str(arg)
        return None

    # find jump targets so they get labels
    targets = set()
    for i in range(0, len(bytecode), 2):
        op, arg = bytecode[i], bytecode[i + 1]
        if op not in MNEMONICS:
            raise AsmError(f"unknown opcode {op} at word {i}")
        if MNEMONICS[op] in ("JMP", "JLT", "JEQ"):
            if not 0 <= arg <= len(bytecode) - 2 or arg % 2 != 0:
                raise AsmError(f"jump target {arg} is not a valid address")
            targets.add(arg)

    label_of = {addr: f"L{i}" for i, addr in enumerate(sorted(targets))}
    addr_of_label = {v: k for k, v in label_of.items()}

    lines = []
    i = 0
    while i < len(bytecode):
        if i in addr_of_label:
            lines.append(f"{addr_of_label[i]}:")
        op, arg = bytecode[i], bytecode[i + 1]
        m = MNEMONICS[op]
        a = fmt_arg(op, arg)
        lines.append(f"{m} {a}" if a is not None else m)
        i += 2
    return "\n".join(lines) + ("\n" if lines else "")
