from asm import OPCODES


class VMError(Exception):
    pass


class Machine:
    NUM_REGS = 8

    def __init__(self):
        self.regs = [0] * self.NUM_REGS
        self.stack = []
        self.out = []
        self.halted = False

    def run(self, bytecode, max_steps=1_000_000):
        """Execute bytecode, return list of values written by OUT."""
        self.regs = [0] * self.NUM_REGS
        self.stack = []
        self.out = []
        self.halted = False

        code = bytecode
        pc = 0
        steps = 0
        n = len(code)
        while not self.halted:
            if steps >= max_steps:
                raise VMError("step limit exceeded (infinite loop?)")
            steps += 1
            if pc < 0 or pc >= n:
                raise VMError(f"pc {pc} out of bounds")
            op, arg = code[pc], code[pc + 1]

            if op == OPCODES["PUSH"]:
                self.stack.append(arg)
            elif op == OPCODES["LOAD"]:
                self._check_reg(arg, pc)
                self.stack.append(self.regs[arg])
            elif op == OPCODES["STORE"]:
                self._check_reg(arg, pc)
                self.regs[arg] = self._pop(pc)
            elif op == OPCODES["ADD"]:
                b, a = self._pop2(pc)
                self.stack.append(a + b)
            elif op == OPCODES["SUB"]:
                b, a = self._pop2(pc)
                self.stack.append(a - b)
            elif op == OPCODES["MUL"]:
                b, a = self._pop2(pc)
                self.stack.append(a * b)
            elif op == OPCODES["CMP"]:
                b, a = self._pop2(pc)
                self.stack.append((a > b) - (a < b))
            elif op == OPCODES["JMP"]:
                pc = arg
                continue
            elif op == OPCODES["JLT"]:
                if self._pop(pc) < 0:
                    pc = arg
                    continue
            elif op == OPCODES["JEQ"]:
                if self._pop(pc) == 0:
                    pc = arg
                    continue
            elif op == OPCODES["OUT"]:
                self.out.append(self._pop(pc))
            elif op == OPCODES["HALT"]:
                self.halted = True
                break
            else:
                raise VMError(f"unknown opcode {op} at pc {pc}")
            pc += 2
        return self.out

    def _pop(self, pc):
        if not self.stack:
            raise VMError(f"stack underflow at pc {pc}")
        return self.stack.pop()

    def _pop2(self, pc):
        if len(self.stack) < 2:
            raise VMError(f"stack underflow at pc {pc}")
        b = self.stack.pop()
        a = self.stack.pop()
        return b, a

    @staticmethod
    def _check_reg(r, pc):
        if not 0 <= r < Machine.NUM_REGS:
            raise VMError(f"bad register {r} at pc {pc}")


def run(bytecode):
    """Convenience wrapper: run bytecode and return OUT sequence."""
    return Machine().run(bytecode)
